package com.yuegang.zhihui.ai.application;import com.yuegang.zhihui.ai.api.*;import com.yuegang.zhihui.common.core.*;import java.time.ZoneOffset;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;public final class ConversationService{private final JdbcTemplate jdbc;public ConversationService(DataSource d){jdbc=new JdbcTemplate(d);}public List<ConversationView>list(long user,int limit){return jdbc.query("SELECT id,title,status,updated_at FROM ai_conversation WHERE user_id=? ORDER BY updated_at DESC LIMIT ?",(r,n)->new ConversationView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getTimestamp(4).toLocalDateTime().atOffset(ZoneOffset.UTC)),user,Math.max(1,Math.min(limit,100)));}public List<MessageView>messages(long user,String conversation){long id=id(conversation);Integer owned=jdbc.queryForObject("SELECT COUNT(*) FROM ai_conversation WHERE id=? AND user_id=?",Integer.class,id,user);if(owned!=1)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return jdbc.query("SELECT id,role,content,refused,created_at FROM ai_message WHERE conversation_id=? ORDER BY created_at,id",(r,n)->new MessageView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getBoolean(4),r.getTimestamp(5).toLocalDateTime().atOffset(ZoneOffset.UTC)),id);}public void feedback(long user,FeedbackRequest request){long message=id(request.messageId());Integer owned=jdbc.queryForObject("SELECT COUNT(*) FROM ai_message m JOIN ai_conversation c ON c.id=m.conversation_id WHERE m.id=? AND c.user_id=? AND m.role='ASSISTANT'",Integer.class,message,user);if(owned!=1)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);jdbc.update("INSERT INTO ai_feedback(id,message_id,user_id,helpful,comment) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE helpful=VALUES(helpful),comment=VALUES(comment)",next(),message,user,request.helpful(),request.comment());}private static long id(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
